#include <iostream>
#include <string>

struct Part {
    unsigned int partNumber{0};
    char partName[25]{""};
};

void printPartByPtr(const Part* ptr) {
    if (ptr != nullptr) {
        std::cout << "Part #" << ptr->partNumber << ": " << ptr->partName << "\n";
    }
}

int main() {
    // Khởi tạo struct và mảng struct
    Part a{101, "Gearbox"};
    Part b[10]{}; // Các phần tử còn lại tự động điền 0

    // Thao tác gán hợp lệ giữa hai struct cùng kiểu
    b[3] = a;

    // Con trỏ trỏ đến mảng
    Part* ptr = b;

    // In phần tử thứ 3 thông qua con trỏ và toán tử ->
    printPartByPtr(ptr + 3);

    return 0;
}

#include <iostream>

// Khai báo struct sử dụng Bit Fields
struct BitFlags {
    unsigned int isReady    : 1; // 1 bit (0 hoặc 1)
    unsigned int isRunning  : 1; // 1 bit
    unsigned int errorCode  : 4; // 4 bit (giá trị 0-15)
};

// Hàm nhân số nguyên không dấu với 2^pow bằng toán tử dịch trái (<<)
unsigned int power2(unsigned int number, unsigned int pow) {
    return number << pow;
}

int main() {
    BitFlags flags{1, 0, 7};
    std::cout << "Ready: " << flags.isReady
              << ", Running: " << flags.isRunning
              << ", Error: " << flags.errorCode << "\n";

    // Thao tác dịch bit
    unsigned int val = 5; // 5 * 2^3 = 40
    unsigned int res = power2(val, 3);
    std::cout << val << " * 2^3 = " << res << "\n";

    // Mặt nạ bit (Masking)
    unsigned int mask = 0x0F;
    unsigned int data = 0xAB;
    std::cout << "Masked data: " << std::hex << (data & mask) << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <cstring>
#include <cstdint>

struct Address {
    char city[16];
    char zipCode[6];
};

struct Customer {
    std::string name;
    unsigned int id;
    Address personal;
};

union DataStore {
    std::uint32_t rawValue;
    std::uint8_t bytes[4];
};

int main() {
    Customer cust{"Alice", 101, {"Hanoi", "10000"}};
    Customer* custPtr = &cust;

    // Direct vs indirect access
    std::cout << cust.name << " lives in " << cust.personal.city << "\n";
    std::cout << custPtr->name << " lives in " << custPtr->personal.city << "\n";

    // Demonstrating union shared storage
    DataStore store;
    store.rawValue = 0x12345678;
    std::cout << "store.rawValue: 0x" << std::hex << store.rawValue << std::dec << "\n";

    // Standard-compliant inspection via memcpy
    std::uint8_t buffer[4];
    std::memcpy(buffer, &store.rawValue, sizeof(buffer));
    std::cout << "First byte in memory: 0x" << std::hex << static_cast<int>(buffer[0]) << std::dec << "\n";

    return 0;
}

#include <iostream>
#include <bitset>
#include <cstdint>

bool isMultipleOf1024(std::uint32_t num) {
    // Lowest 10 bits must all be 0 (mask 0x3FF is 1111111111 in binary)
    return (num & 0x3FF) == 0;
}

std::uint32_t packCharacters(char c1, char c2, char c3, char c4) {
    std::uint32_t packed = static_cast<std::uint8_t>(c1);
    packed = (packed << 8) | static_cast<std::uint8_t>(c2);
    packed = (packed << 8) | static_cast<std::uint8_t>(c3);
    packed = (packed << 8) | static_cast<std::uint8_t>(c4);
    return packed;
}

void unpackCharacters(std::uint32_t packed, char& c1, char& c2, char& c3, char& c4) {
    c1 = static_cast<char>((packed & 0xFF000000) >> 24);
    c2 = static_cast<char>((packed & 0x00FF0000) >> 16);
    c3 = static_cast<char>((packed & 0x0000FF00) >> 8);
    c4 = static_cast<char>(packed & 0x000000FF);
}

int main() {
    char a = 'C', b = 'P', c = 'P', d = '7';
    std::uint32_t packed = packCharacters(a, b, c, d);
    std::cout << "Packed bits: " << std::bitset<32>(packed) << "\n";

    char u1, u2, u3, u4;
    unpackCharacters(packed, u1, u2, u3, u4);
    std::cout << "Unpacked: " << u1 << u2 << u3 << u4 << "\n";

    std::cout << "2048 is multiple of 1024: " << std::boolalpha << isMultipleOf1024(2048) << "\n";
    std::cout << "2050 is multiple of 1024: " << std::boolalpha << isMultipleOf1024(2050) << "\n";

    return 0;
}

#include <iostream>
#include <cstring>
#include <string>
#include <string_view>

int main() {
    // --- 1. Sửa lỗi mảng chuỗi C-style ---
    char legacy_buf[16];
    std::strncpy(legacy_buf, "hello", 5);
    legacy_buf[5] = '\0'; // Bắt buộc phải có null-terminator

    const char* str1 = "test";
    const char* str2 = "test";
    bool legacy_equal = (std::strcmp(str1, str2) == 0); // So sánh đúng trong C

    // --- 2. Tiếp cận hiện đại với C++17 ---
    std::string modern_str = "hello";
    std::string_view sv = "Welcome Home";

    // So sánh trực quan và an toàn
    bool modern_equal = (modern_str == "hello");

    std::cout << "Legacy buffer: " << legacy_buf << "\n";
    std::cout << "Legacy equal check: " << (legacy_equal ? "true" : "false") << "\n";
    std::cout << "Modern string: " << modern_str << "\n";
    std::cout << "Modern view prefix: " << sv.substr(0, 7) << "\n";
    std::cout << "Modern equal check: " << (modern_equal ? "true" : "false") << "\n";

    return 0;
}
